for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i; pairs[i]=j

bases='ACGU'
comp={'A':'U','U':'A','G':'C','C':'G'}

def rand_init():
    s=['A']*n
    for i,j in list(pairs.items()):
        if i<j:
            s[i]='G'; s[j]='C'
    return s

random.seed(123)
best=None; best_d=999; best_e=None
for trial in range(20):
    cur = rand_init()
    for pos in range(n):
        if pos not in pairs:
            cur[pos]=random.choice(bases)
    cur_seq=''.join(cur)
    fc=RNA.fold_compound(cur_seq)
    mfe,cur_e=fc.mfe()
    cur_d=RNA.bp_distance(mfe,target)
    for it in range(1500):
        pos=random.randrange(n)
        old=cur[pos]
        oldj=None
        if pos in pairs:
            j=pairs[pos]
            oldj=cur[j]
            newb=random.choice(bases)
            cur[pos]=newb
            cur[j]=comp[newb]
        else:
            newb=random.choice(bases)
            cur[pos]=newb
        seq=''.join(cur)
        fc=RNA.fold_compound(seq)
        mfe,e=fc.mfe()
        d=RNA.bp_distance(mfe,target)
        accept = d<cur_d or (d==cur_d and e<cur_e)
        if accept:
            cur_d=d; cur_e=e
